mapper.select:
select ccb.*, hbm.bp_code, (select meaning from sys_code_value_b_v where code = 'FND.BP_CLASS' and code_value = ccb.bp_class) bp_class_n, hbm.WORKING_PLACE, hbm.POSITION, (select meaning from sys_code_value_b_v where code = 'HLS211_GENDER' and code_value = hbm.GENDER) gender_n, hbm.GENDER, hbm.MARITAL_STATUS, (select meaning from sys_code_value_b_v where code = 'HLS211_MARITAL_STATUS' and code_value = hbm.MARITAL_STATUS) MARITAL_STATUS_N, hbm.AGE, hbm.DATE_OF_BIRTH, hbm.ANNUAL_INCOME, hbm.NUMBER_OF_CHILDREN, hbm.INDUSTRY, (select DESCRIPTION from hls_stat_class where CLASS_USAGE = 'BIZ_PARTNER' and CLASS_CODE = hbm.INDUSTRY) industry_n, hbm.COMPANY_NATURE, (select meaning from sys_code_value_b_v where code = 'PRJ_NATURE_OF_BUSINESS' and code_value = hbm.COMPANY_NATURE) company_nature_n, hbm.ACTUAL_CONTROLLER, hbm.LEGAL_PERSON, hbm.FOUNDED_DATE, hbm.REGISTERED_CAPITAL, hbm.PAID_UP_CAPITAL, hbm.CREDIT_RATING, hbm.LISTED_COMPANY_FLAG, hbm.ENTERPRISE_SCALE, (select meaning from sys_code_value_b_v where code = 'ENTERPRISE_SCALE_TYPE' and code_value = hbm.ENTERPRISE_SCALE) enterprise_scale_n, hbm.SALE_TYPE, (select meaning from sys_code_value_b_v where code = 'HR_SALE_TYPE' and code_value = hbm.SALE_TYPE) sale_type_n from con_contract_bp ccb, hls_bp_master hbm where hbm.bp_id = ccb.bp_id
and ccb.contract_id = #{contractId}
and ccb.bp_category = #{bpCategory}

select hbm.BP_ID,hbm.BP_CODE,hbm.BP_NAME,hbm.BP_CLASS,hbm.EXTRA_NAM,hbm.enabled_flag,hbt.description bpClassN,hbpt.description bpTypeN ,su.DESCRIPTION ownerUserIdN, (select hbc.description from hls_bp_category hbc where hbc.bp_category=hbm.bp_category) bp_category_n from hls_bp_master hbm left join hls_business_type hbt on hbm.bp_class = hbt.business_type and hbt.document_category = 'HLS_BP_MASTER' left join hls_bp_type hbpt on hbm.bp_type = hbpt.bp_type left join sys_user su on hbm.owner_user_id = su.user_id
hbm.bp_category!='CREDIT_ORGANIZATION'
and hbm.bp_code >= #{bpCodeFromN}
and hbm.bp_code <= #{bpCodeToN}
and hbm.bp_code = #{bpCode}
and hbm.bp_name like concat('%', concat(#{bpName,jdbcType=VARCHAR}, '%'))
and hbm.bp_class = #{bpClass}
and hbm.bp_type like concat('%', concat(#{bpType,jdbcType=VARCHAR}, '%'))
and hbm.extra_nam like concat('%', concat(#{extraNam,jdbcType=VARCHAR}, '%'))
and hbm.enabled_flag = #{enabledFlag}
and hbm.owner_user_id = #{ownerUserId}
and EXISTS(SELECT ppb.BP_ID FROM prj_project_bp ppb,prj_project pp where pp.PROJECT_ID= ppb.PROJECT_ID AND ppb.BP_ID = hbm.BP_ID and pp.PROJECT_NUMBER = #{projectNumber})
and EXISTS(SELECT ppb.BP_ID FROM prj_project_bp ppb,prj_project pp where pp.PROJECT_ID= ppb.PROJECT_ID AND ppb.BP_ID = hbm.BP_ID and pp.PROJECT_NAME like concat('%', concat(#{projectName,jdbcType=VARCHAR}, '%')))
AND EXISTS (SELECT ccb.BP_ID FROM con_contract_bp ccb,con_contract cc WHERE ccb.BP_ID = hbm.BP_ID AND cc.contract_id = ccb.contract_id and cc.contract_id = #{contractId})
AND EXISTS (SELECT ccb.BP_ID FROM con_contract_bp ccb,con_contract cc WHERE ccb.BP_ID = hbm.BP_ID AND cc.contract_id = ccb.contract_id and cc.contract_number = #{contractNumber})
AND EXISTS (SELECT ccb.BP_ID FROM con_contract_bp ccb,con_contract cc WHERE ccb.BP_ID = hbm.BP_ID AND cc.contract_id = ccb.contract_id and cc.contract_name like concat('%', concat(#{contractName,jdbcType=VARCHAR}, '%')))
AND EXISTS (SELECT ppb.BP_ID FROM hls_lease_organization o,prj_project pp,prj_project_bp ppb WHERE o.lease_organization = pp.lease_organization AND pp.PROJECT_ID= ppb.PROJECT_ID AND ppb.BP_ID = hbm.BP_ID AND o.lease_organization like concat('%', concat(#{unitId,jdbcType=VARCHAR}, '%')))
order by hbm.creation_date desc

select hbm.bp_id, hbm.bp_code, hbm.bp_name, hbm.bp_name as bp_id_n, hbm.bp_class, hbm.extra_nam, hbm.external_bp_code, hbm.enabled_flag, hbm.enterprise_scale, hbm.industry, hbm.legal_form, hbm.legal_representative, hbm.actual_controller, hbm.registered_place, hbm.registered_date, hbm.registered_capital, hbm.paid_in_capital, hbm.enterprise_unified_credit_code, hbm.founded_date, hbm.business_license_num, hbm.organization_code, hbm.tax_registry_num, hbm.loan_card_num, hbm.loan_card_password, hbm.taxpayer_type, hbm.invoice_title, hbm.invoice_bp_address_phone_num, hbm.invoice_bp_bank_account, hbm.nationality, hbm.date_of_birth, hbm.native_place, hbm.id_type, hbm.id_card_no, hbm.marital_status, hbm.academic_background, hbm.age, hbm.gender, hbm.annual_income, hbm.working_company, hbm.company_industry, hbm.business_job, hbm.working_years, hbm.phone, hbm.cell_phone, hbm.email, hbm.primaryiness, hbm.authority_rule_string, hbm.associated_division, hbm.three_certificates, hbm.operating_period_start, hbm.operating_period_end, hbm.environmental_level, hbm.group_customers, hbm.liabilities, hbm.situation_description, hbm.main_experience, hbm.family_name, hbm.family_gender, hbm.family_relationship, hbm.family_academic_background, hbm.family_id_type, hbm.family_id_card_no, hbm.family_date_of_birth, hbm.family_contact_information, hbm.family_contact_address, hbm.object_version_number, hbm.last_update_login, hbm.request_id, hbm.program_id, hbm.created_by, hbm.last_updated_by, hbm.creation_date, hbm.last_update_date, hbm.domestic_oversea, hbm.local_nonlocal, hbm.org_type, hbm.start_active_date, hbm.end_active_date, hbm.company_information, hbm.main_products, hbm.primary_business, hbm.bp_eng_name, hbm.agency_credit_code, hbm.bp_financial_type, hbm.registration_num_type, hbm.register_cert_num, hbm.account_license_num, hbm.register_capital_cur, hbm.economic_indu_classify, hbm.economic_indu_class_sec, hbm.economic_indu_class_thr, hbm.internal_indu, hbm.high_risk_indu, hbm.organization_type, hbm.organization_type_details, hbm.bp_classify, hbm.credit_line_amount, hbm.credit_type, hbm.credit_currency, hbm.valid_from, hbm.valid_to, hbm.company_id, hbm.bank_id, hbm.rele_com_flag, hbm.family_id_address, hbm.inter_status, hbm.inter_info, hbm.save_flag, hbm.data_class, hbm.change_req_id, hbm.bp_factor, hbm.bp_category, hbm.fin_note, hbm.owner_user_id, hbm.fin_org_type, hbm.enterprise_unified_creditcode, hbm.bank_code, hbm.bank_short_name, hbm.bp_title, hbm.number_of_children, hbm.period_in_job, hbm.place_of_birth, hbm.ref_v02, hbm.currency, hbm.exclusive_trade, hbm.customer_nature, hbm.enterprise_nature, hbm.economic_zone, hbm.business_classification, hbm.holding_type, hbm.listed_company, hbm.local_finance, hbm.exit_financing, hbm.customer_number, hbm.business_area, hbm.enterprise_affiliation, hbm.credit_customer, hbm.swift, TABALL.NAME, TABALL.UNIT_NAME, hbt.description bp_class_n, hbpt.description bp_type_n, hbm.paid_up_capital, hbm.ref_v01, hbm.legal_person, hbm.group_membership from hls_bp_master hbm LEFT JOIN hls_business_type hbt ON hbm.bp_class = hbt.business_type AND hbt.document_category = 'HLS_BP_MASTER' LEFT JOIN hls_bp_type hbpt ON hbm.bp_type = hbpt.bp_type LEFT JOIN (SELECT FE.NAME,SUA.USER_ID,MIN(FOU.UNIT_NAME) UNIT_NAME,SUA.COMPANY_ID FROM SYS_USER_ALLOCATION SUA LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID=FOU.UNIT_ID, (SELECT MIN(COMPANY_ID) COMPANY_ID,USER_ID FROM SYS_USER_ALLOCATION GROUP BY USER_ID ORDER BY USER_ID ASC ) SUAC, FND_EMPLOYEE FE WHERE SUA.COMPANY_ID = FEA.COMPANY_ID AND SUA.COMPANY_ID = FOU.COMPANY_ID AND SUA.COMPANY_ID = SUAC.COMPANY_ID AND SUA.USER_ID = SUAC.USER_ID AND FE.EMPLOYEE_ID = FEA.EMPLOYEE_ID GROUP BY SUA.USER_ID,SUA.COMPANY_ID,FE.NAME ORDER BY SUA.USER_ID ASC) TABALL ON hbm.CREATED_BY = TABALL.USER_ID right join HLS_MARKETING_REPORT_BP hmeb on hmeb.bp_id = hbm.bp_id
and hbm.bp_id = #{bpId}
and hbm.bp_name LIKE concat(CONCAT('%',#{bpName}),'%')
and hbm.bp_code LIKE concat(CONCAT('%',#{bpCode}),'%')
and hmeb.bp_type = #{bpType}
and hbm.bp_categroy = #{bpCategroy}
and hmeb.marketing_report_id = #{marketingReportId}
and hbm.bp_class = #{bpClass}

SELECT hbm.*, hbt.description bpClassN,su.DESCRIPTION ownerUserIdN, hbpt.description bpTypeN, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'CHS.CURRENCY_TYPE' AND v.code_value = hbm.REGISTERED_CAPITAL_CURRENCY) registered_capital_currency_n, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'BP.ECONOMIC_SECTOR_THR' and sc.code_value_id = hbm.economic_sector) economic_sector_n, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'FND.ORGTYPESUB' and sc.code_value_id = hbm.organization_type) organization_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'CHS.CURRENCY_TYPE' AND v.code_value = hbm.ACTUAL_CURRENCY) actual_currency_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'FND.ENTERPRISE_SCALE_TYPE' AND v.code_value = hbm.LEGAL_FORM) legal_form_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'HLS.CUSTOMER_GROUP' AND v.code_value = hbm.BP_FINANCIAL_TYPE) bp_financial_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SUBSISTING_STATUS' AND v.code_value = hbm.EXISTENCE_STATUS) existence_status_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'FND.COMPANY_TYPE' AND v.code_value = hbm.enterprise_nature) enterprise_nature_n, -- ( SELECT t.value_name -- FROM (SELECT v.code_value_id tree_node_id, -- v.code_value_id value_code, -- v.code_value, -- v.MEANING value_name, -- v.parent_code_value_id parent_tree_node_id, -- v.MEANING tree_node_desc -- FROM sys_code_value_b_v v -- WHERE V.CODE IN ('BP.ECONOMIC_SECTOR', -- 'BP.ECONOMIC_SECTOR_SEC', -- 'BP.ECONOMIC_SECTOR_THR') -- AND FIND_IN_SET(v.code_value_id, getChildList(v.code_value_id)) != 0 -- ORDER BY v.code_id) t -- -- where t.value_code = hbm.ECONOMIC_INDU_CLASSIFY) economic_indu_classify_n, nvl((select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'FND.INDUSTRY_2' and sc.code_value = hbm.economic_indu_classify), (SELECT t.description FROM hls_stat_class t WHERE t.class_usage = 'BIZ_PARTNER' AND t.enabled_flag = 'Y' and to_char(t.CLASS_ID) = hbm.economic_indu_classify) ) economic_indu_classify_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'EQUIPMENT_TYPE' AND v.code_value = hbm.equipment_type) equipment_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'ORGANIZATION_TYPE' AND v.code_value = hbm.asset_type) asset_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'BP.REGISTRATION_NUM_TYPE' AND v.code_value = hbm.REGISTRATION_NUM_TYPE) registration_num_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SYS.YES_NO' AND v.code_value = hbm.ref_v01) ref_v01_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SYS.YES_NO' AND v.code_value = hbm.GROUP_ENTERPRISE_FLAG) group_enterprise_flag_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'FND.SHAREHOLDER_CERT_TYPE' AND v.code_value = hbm.ID_TYPE) idTypeN, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'FND.SHAREHOLDER_CERT_TYPE' AND v.code_value = hbm.ACTUAL_TYPE) actualTypeN,
( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'PROFIT_CENTER' AND v.code_value = REF_V05 ) refV05N, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'PRJ_NATURE_OF_BUSINESS' AND v.code_value = company_nature ) companyNatureN, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'HLS211_BP_CLASS' AND v.code_value = BP_NAME_SP_CLASS ) bpNameSpClassN, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'ZX_CERTTYPE' AND v.code_value = ACTUAL_CONTROLLER_ID_TYPE ) actualControllerIdTypeN, (select currency_name from fnd_currency where currency_code = currency) currencyN, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'SYS.YES_NO' AND v.code_value = LICENSE_TERMS_IF_LONG )licenseTermsIfLongN, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'RSC_CREDIT_RATING' AND v.code_value = CREDIT_RATING )creditRatingN, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'MARKET_LOCATION' AND v.code_value = MARKET_LOCATION )marketLocationN, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'ENTERPRISE_SCALE_TYPE' AND v.code_value = ENTERPRISE_SCALE )enterpriseScaleN, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'HR_SALE_TYPE' AND v.code_value = SALE_TYPE )saleTypeN, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'HOSPITAL_QUALIFICATION' AND v.code_value = REF_V06 )refV06N, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'HOSPITAL_CATEGORY' AND v.code_value = REF_V07 )refV07N, ( select country_name from fnd_country where country = nationality ) nationalityN, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'HLS211_TAXPAYER_TYPE' AND v.code_value = TAXPAYER_TYPE )taxpayerTypeN, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'ACR510_INVOICE_KIND' AND v.code_value = INVOICE_KIND )invoiceKindN, (select v.meaning from sys_code_value_b_v v where v.code = 'SYS.YES_NO' and v.code_value = hbm.if_to_zx_flag) as ifToZxFlagN, (select bc.description from hls_bp_category bc where bc.bp_category = hbm.bp_category) as bpCategoryN, (select DESCRIPTION from hls_stat_class where CLASS_USAGE = 'BIZ_PARTNER' and to_char(class_id) = hbm.INDUSTRY) industry_n FROM hls_bp_master hbm LEFT JOIN hls_business_type hbt ON hbm.bp_class = hbt.business_type AND hbt.document_category = 'HLS_BP_MASTER' LEFT JOIN hls_bp_type hbpt ON hbm.bp_type = hbpt.bp_type LEFT JOIN sys_user su ON hbm.owner_user_id = su.user_id
and hbm.bp_id = #{bpId}

select hbm.bp_name,hbm.bp_id from hls_bp_master hbm
1=1
and replace(hbm.bp_name,' ','') = #{bpName}

select hbm.BP_ID,hbm.BP_CODE,hbm.BP_NAME,hbm.BP_CLASS,hbm.EXTRA_NAM,hbm.enabled_flag,hbt.description bpClassN,hbpt.description bpTypeN ,su.DESCRIPTION ownerUserIdN, hbm.bp_category, (select hbc.description from hls_bp_category hbc where hbc.bp_category=hbm.bp_category) bp_category_n, hbm.bp_approve_status, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'HLS_WFL_STATUS' AND v.code_value = nvl(hbm.bp_approve_status, 'NEW')) bp_approve_status_n, (select distinct fou.unit_name from sys_user_allocation su,fnd_employee_assigns fea,fnd_org_unit fou where su.user_id = hbm.owner_user_id and su.employee_assign_id = fea.employee_assign_id and fou.unit_id = fea.unit_id and fea.primary_position_flag = 'Y' and su.enabled_flag = 'Y' and fea.enabled_flag = 'Y') unit_id_n, to_char(hbm.creation_date,'yyyy-mm-dd') creation_date_n from hls_bp_master hbm left join hls_business_type hbt on hbm.bp_class = hbt.business_type and hbt.document_category = 'HLS_BP_MASTER' left join hls_bp_type hbpt on hbm.bp_type = hbpt.bp_type left join sys_user su on hbm.owner_user_id = su.user_id
exists (select 1 from hls_bp_master_role hbmr where hbmr.bp_id = hbm.bp_id and hbmr.bp_category in ('VENDER', 'DEALER')) AND hbm.bp_category!='HLS_BP_CREDIT' AND hbm.bp_category != 'MANUFACTURER' AND ((#{userId} IN (SELECT SUA.USER_ID FROM FND_ORG_POSITION FOP, FND_EMPLOYEE_ASSIGNS FEA, SYS_USER_ALLOCATION SUA WHERE FOP.POSITION_CODE = 'DEPT0230_POSITION010' AND FEA.POSITION_ID = FOP.POSITION_ID AND FEA.ENABLED_FLAG = 'Y' AND FEA.PRIMARY_POSITION_FLAG = 'Y' AND SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID AND SUA.ENABLED_FLAG = 'Y') AND HBM.BP_CATEGORY NOT IN ('MANUFACTURER','VENDER') ) OR (#{userId} IN (SELECT SUA.USER_ID FROM FND_ORG_POSITION FOP, FND_EMPLOYEE_ASSIGNS FEA, SYS_USER_ALLOCATION SUA WHERE FOP.POSITION_CODE = 'DEPT0230_POSITION020' AND FEA.POSITION_ID = FOP.POSITION_ID AND FEA.ENABLED_FLAG = 'Y' AND FEA.PRIMARY_POSITION_FLAG = 'Y' AND SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID AND SUA.ENABLED_FLAG = 'Y') AND HBM.BP_CATEGORY NOT IN ('MANUFACTURER','VENDER','DEALER') ) OR (#{userId} IN (SELECT SUA.USER_ID FROM FND_ORG_POSITION FOP, FND_EMPLOYEE_ASSIGNS FEA, SYS_USER_ALLOCATION SUA WHERE FOP.POSITION_CODE = 'DEPT0230_POSITION030' AND FEA.POSITION_ID = FOP.POSITION_ID AND FEA.ENABLED_FLAG = 'Y' AND FEA.PRIMARY_POSITION_FLAG = 'Y' AND SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID AND SUA.ENABLED_FLAG = 'Y') AND HBM.BP_CATEGORY NOT IN ('MANUFACTURER','MANAGEMENT_COMPANY') or #{userId} NOT IN (SELECT SUA.USER_ID FROM FND_ORG_POSITION FOP, FND_EMPLOYEE_ASSIGNS FEA, SYS_USER_ALLOCATION SUA WHERE FOP.POSITION_CODE IN ('DEPT0230_POSITION030','DEPT0230_POSITION020','DEPT0230_POSITION010') AND FEA.POSITION_ID = FOP.POSITION_ID AND FEA.ENABLED_FLAG = 'Y' AND FEA.PRIMARY_POSITION_FLAG = 'Y' AND SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID AND SUA.ENABLED_FLAG = 'Y'))) and bp_approve_status!='APPROVED'
and hbm.bp_code >= #{bpCodeFromN}
and hbm.bp_code <= #{bpCodeToN}
and hbm.bp_code like concat('%', concat(#{bpCode,jdbcType=VARCHAR}, '%'))
and hbm.bp_name like concat('%', concat(#{bpName,jdbcType=VARCHAR}, '%'))
and hbm.bp_class = #{bpClass}
and hbm.bp_type like concat('%', concat(#{bpType,jdbcType=VARCHAR}, '%'))
and hbm.extra_nam like concat('%', concat(#{extraNam,jdbcType=VARCHAR}, '%'))
and hbm.enabled_flag = #{enabledFlag}
and hbm.owner_user_id_n like concat('%', concat(#{ownerUserIdN,jdbcType=VARCHAR}, '%'))
and (select fou.unit_name from sys_user_allocation su,fnd_employee_assigns fea,fnd_org_unit fou where su.user_id = hbm.owner_user_id and su.employee_assign_id = fea.employee_assign_id and fou.unit_id = fea.unit_id and fea.primary_position_flag = 'Y' and su.enabled_flag = 'Y' and fea.enabled_flag = 'Y') like concat('%', concat(#{unitName,jdbcType=VARCHAR}, '%'))
and hbm.bp_approve_status = #{bpApproveStatus}
order by hbm.bp_id desc

select hbm.BP_ID, hbm.BP_NAME, hbm.BP_CODE, hbm.CELL_PHONE, hbm.BP_CLASS, hbm.AGE
from hls_bp_master hbm
where hbm.BP_ID = #{bpId}
